def movie_text(movie):
    return " ".join([movie["title"], " ".join(movie["genres"]), " ".join(movie["keywords"]), movie["overview"], movie["language"]]).lower()

def cosine_text_similarity(a, b):
    # Lightweight token cosine similarity; no extra ML library required.
    stop = {"the", "a", "an", "and", "to", "of", "in", "on", "with", "is", "for", "his", "her", "their", "from"}
    ta = [w for w in movie_text(a).replace(",", " ").replace(".", " ").split() if w not in stop]
    tb = [w for w in movie_text(b).replace(",", " ").replace(".", " ").split() if w not in stop]
    if not ta or not tb:
        return 0.0
    ca, cb = defaultdict(int), defaultdict(int)
    for w in ta: ca[w] += 1
    for w in tb: cb[w] += 1
    dot = sum(v * cb.get(k, 0) for k, v in ca.items())
    na = math.sqrt(sum(v*v for v in ca.values()))
    nb = math.sqrt(sum(v*v for v in cb.values()))
    return dot / (na * nb) if na and nb else 0.0

def cosine_user_similarity(ratings_a, ratings_b):
    common = set(ratings_a) & set(ratings_b)
    if len(common) < 2:
        return 0.0
    aa = [ratings_a[i] - 3 for i in common]
    bb = [ratings_b[i] - 3 for i in common]
    dot = sum(x*y for x, y in zip(aa, bb))
    na = math.sqrt(sum(x*x for x in aa))
    nb = math.sqrt(sum(y*y for y in bb))
    return dot / (na*nb) if na and nb else 0.0

POSTER_CACHE = {}

def get_poster(title, year=None):
    cache_key = (title, year)
    if cache_key in POSTER_CACHE:
        return POSTER_CACHE[cache_key]
    if not TMDB_API_KEY:
        return ""
    try:
        params = {"api_key": TMDB_API_KEY, "query": title, "include_adult": "false"}
        if year:
            params["year"] = year
        response = requests.get(f"{TMDB_API_BASE}/search/movie", params=params, timeout=4)
        response.raise_for_status()
        results = response.json().get("results", [])
        if not results:
            POSTER_CACHE[cache_key] = ""
            return ""
        # Favor exact-ish title match when available.
        chosen = next((r for r in results if r.get("title", "").lower() == title.lower()), results[0])
        path = chosen.get("poster_path")
        poster = f"{TMDB_IMAGE_BASE}{path}" if path else ""
        POSTER_CACHE[cache_key] = poster
        return poster
    except requests.RequestException:
        return ""

def recommendations(selected_id, history_ids, liked_ids, disliked_ids, genres, language, age_group, limit=8):
    by_id = {m["id"]: m for m in MOVIES}
    selected = by_id.get(selected_id)
    history_ids = set(history_ids)
    liked_ids = set(liked_ids)
    disliked_ids = set(disliked_ids)
    excluded = history_ids | liked_ids | disliked_ids | {selected_id}

    # Aggregate user's explicit ratings: likes are positive, dislikes are negative.
    user_ratings = {mid: 5 for mid in liked_ids}
    user_ratings.update({mid: 1 for mid in disliked_ids})
    if selected_id:
        user_ratings[selected_id] = 4

    # Profile preferences are soft signals, not deterministic assumptions.
    preferred_genres = set(genres or [])
    preferred_language = language or "Any"
    profile_words = {
        "under_18": {"school", "childhood", "family", "coming of age"},
        "18_24": {"college", "coming of age", "friendship", "career", "youth"},
        "25_34": {"career", "relationships", "family", "ambition"},
        "35_plus": {"family", "relationships", "history", "biography"},
        "prefer_not": set(),
    }.get(age_group, set())

    # User-based collaborative score using demo profiles plus current user's history.
    collab_scores = defaultdict(float)
    sim_totals = defaultdict(float)
    for _, ratings in DEMO_RATINGS.items():
        sim = cosine_user_similarity(user_ratings, ratings)
        if sim <= 0:
            continue
        for mid, rating in ratings.items():
            if mid not in excluded and rating >= 4:
                collab_scores[mid] += sim * rating
                sim_totals[mid] += sim
    for mid in list(collab_scores):
        collab_scores[mid] = collab_scores[mid] / sim_totals[mid] if sim_totals[mid] else 0

    results = []
    for movie in MOVIES:
        mid = movie["id"]
        if mid in excluded:
            continue
        content = cosine_text_similarity(selected, movie) if selected else 0.0
        # Compare with every liked/history title, not only the selected title.
        other_refs = (liked_ids | history_ids) - {mid}
        history_sim = max((cosine_text_similarity(by_id[r], movie) for r in other_refs if r in by_id), default=0.0)
        genre_score = len(preferred_genres & set(movie["genres"])) / max(1, len(preferred_genres)) if preferred_genres else 0.0
        lang_score = 1.0 if preferred_language == "Any" or movie["language"] == preferred_language else 0.0
        profile_score = sum(1 for w in profile_words if w in movie_text(movie)) / max(1, len(profile_words)) if profile_words else 0.0
        collab = min(1.0, collab_scores.get(mid, 0) / 5.0)
        popularity = movie["rating"] / 10.0

        # Hybrid weighted score. Explainable, tunable weights for a portfolio demo.
        score = (0.34 * content + 0.18 * history_sim + 0.22 * collab +
                 0.12 * genre_score + 0.06 * lang_score +
                 0.03 * profile_score + 0.05 * popularity)
        reasons = []
        if content >= 0.12: reasons.append("similar themes/story")
        if genre_score > 0: reasons.append("your preferred genre")
        if collab > 0.15: reasons.append("liked by similar demo profiles")
        if history_sim >= 0.12: reasons.append("matches your watch history")
        if not reasons: reasons.append("strong overall match")
        results.append({**movie, "score": round(score, 4), "match_percent": round(min(99, score*100), 1), "reasons": reasons, "poster": get_poster(movie["title"], movie["year"])})
    results.sort(key=lambda x: (x["score"], x["rating"]), reverse=True)
    return results[:limit]

@app.route("/")
def index():
    movie_cards = []
    for m in MOVIES:
        movie_cards.append({**m, "poster": ""})
    return render_template("index.html", movies=movie_cards, tmdb_configured=bool(TMDB_API_KEY))

@app.route("/api/poster/<int:movie_id>")
def poster_api(movie_id):
    movie = next((m for m in MOVIES if m["id"] == movie_id), None)
    if not movie:
        return jsonify({"poster": ""}), 404
    return jsonify({"poster": get_poster(movie["title"], movie["year"])})


@app.route("/api/recommend", methods=["POST"])
def recommend_api():
    data = request.get_json(silent=True) or {}
    try:
        selected_id = int(data.get("selected_movie_id", 0))
    except (TypeError, ValueError):
        selected_id = 0
    def ints(values):
        out = []
        for value in values or []:
            try: out.append(int(value))
            except (TypeError, ValueError): pass
        return out
    recs = recommendations(
        selected_id=selected_id,
        history_ids=ints(data.get("history_ids")),
        liked_ids=ints(data.get("liked_ids")),
        disliked_ids=ints(data.get("disliked_ids")),
        genres=data.get("genres", []),
        language=data.get("language", "Any"),
        age_group=data.get("age_group", "prefer_not"),
        limit=8,
    )
    return jsonify({"recommendations": recs, "demo_note": "Collaborative filtering uses clearly labelled synthetic demo profiles until you add real ratings data."})

if __name__ == "__main__":
    app.run(debug=True)
